const content = $json.choices[0].message.content;

// Eliminar todo el razonamiento de Qwen
const cleanContent = content
    .replace(/<think>[\s\S]*?<\/think>/gi, "")
    .trim();

console.log("RESPUESTA LIMPIA:", cleanContent);

const lines = cleanContent
    .split("\n")
    .map(line => line.trim())
    .filter(line => line.length > 0);

const result = lines.find(line => line.includes("|"));

if (!result) {
    throw new Error(
        "Groq no devolvió el formato esperado: " + cleanContent
    );
}

const parts = result.split("|");

if (parts.length !== 3) {
    throw new Error(
        "Formato incorrecto: " + result
    );
}

const amountText = parts[0]
    .trim()
    .replace(",", ".");

const amount = Number(amountText);

if (isNaN(amount)) {
    throw new Error(
        "Monto inválido: " + parts[0]
    );
}

const description = parts[1].trim();
const category = parts[2].trim();

return [
    {
        json: {
            amount,
            description,
            category
        }
    }
];
